<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,Arial;font-size:8px}h2{margin:0 0 4px}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{border:1px solid #777;padding:5px}th{background:#eee}.right{text-align:right}.total{font-weight:bold;text-align:right;margin-top:10px}.summary{margin-top:10px}.summary td{border:0;padding:3px}</style></head><body><h2>LAPORAN PEMBELIAN KOPERASI</h2><div><?=esc($koperasi['nama_koperasi'] ?? '')?></div><div>Periode: <?=esc($from ?: 'awal')?> s/d <?=esc($to ?: 'akhir')?></div><table><thead><tr><th>Tanggal</th><th>No Pembelian</th><th>SPPG</th><th>Supplier</th><th>Status</th><th>Harga Beli</th><th>Harga Jual</th><th>Margin</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['tanggal_pembelian']))?></td><td><?=esc($r['no_pembelian'])?></td><td><?=esc($names[(string)$r['id_sppg']]??$r['id_sppg'])?></td><td><?=esc($r['supplier']??'-')?></td><td><?=esc(match($r['status']){'draft'=>'Draft','dibeli'=>'Sudah Dibeli','dikirim'=>'Dikirim ke SPPG',default=>$r['status']})?></td><td class="right">Rp <?=number_format((float)($r['total_harga_beli']??0),0,',','.')?></td><td class="right">Rp <?=number_format((float)$r['grand_total'],0,',','.')?></td><td class="right">Rp <?=number_format((float)($r['total_margin']??0),0,',','.')?></td></tr><?php endforeach;?></tbody></table><table class="summary"><tr><td>Total Harga Beli</td><td class="right">Rp <?=number_format($grandBuy,0,',','.')?></td></tr><tr><td>Total Harga Jual</td><td class="right">Rp <?=number_format($grand,0,',','.')?></td></tr><tr><td>Total Margin Koperasi</td><td class="right">Rp <?=number_format($grandMargin,0,',','.')?></td></tr></table></body></html>
